use mod.tool
use mod.std.array
use mod.std.object

fn pick_movie(items) {
    for k in array.range(0, array.len(items)) {
        let it = items[k]
        if object.get(it, "qid", "") == "movie" {
            return it
        }
    }
    return items[0]
}

let films = workflow.input.films
let rows = []
for i in array.range(0, array.len(films)) {
    let f = films[i]
    let url = "https://v3.sg.media-imdb.com/suggestion/x/" + f.q + ".json"
    let raw = tool.call_json("net.imdb", {origin: "imdb", url: url})
    let data = raw.parse_json()
    let hit = pick_movie(data.d)
    let img = object.get(hit, "i", {})
    let row = {rank: i + 1, title: object.get(hit, "l", ""), year: object.get(hit, "y", 0), gross: f.gross, stars: object.get(hit, "s", ""), poster: object.get(img, "imageUrl", ""), imdb: object.get(hit, "id", "")}
    array.push(rows, row)
}
let out = {films: rows}
out
